#!/usr/bin/env bash
# Self-contained, checksum-verified Netlify gate installer. Python 3.11+ required.
set -euo pipefail
python3 - <<'INSTALLPY'
import base64, hashlib, json, os, re, tempfile, tomllib
from pathlib import Path
root = Path.cwd()
if not (root / 'netlify.toml').is_file() or not (root / 'package.json').is_file():
    raise SystemExit('Run this installer from the repository root.')
payload = json.loads('{"scripts/verify-netlify.py": {"sha256": "07ddf84a69cdfc3b37362868af484261f53c20d041d96412a1a2e45441f04d59", "data": ""}, "scripts/build-netlify-verified.sh": {"sha256": "65b4d75e00f4d9d0f402dc1e320ced9f5a1ba89c0eda426b1828948fc4cda885", "data": ""}, "tests/test_netlify_gate.py": {"sha256": "db5307dba9e4b2764efd83ff48757332560ee4fe655fdb744090aa4791cecd68", "data": ""}}')
writes = {}
for name, item in payload.items():
    data = base64.b64decode(item['data'], validate=True)
    if hashlib.sha256(data).hexdigest() != item['sha256']:
        raise SystemExit('Installer payload checksum failed: ' + name)
    writes[name] = data
config_text = (root / 'netlify.toml').read_text()
config = tomllib.loads(config_text)
command = 'npm run build:netlify:verified'
for name, context in config.get('context', {}).items():
    if 'command' in context and context['command'] != command:
        raise SystemExit('Context ' + name + ' overrides the build command; reconcile it before installing.')
def set_value(text, section, key, value):
    section_pattern = r'(?ms)^\s*\[' + re.escape(section) + r'\][^\n]*\n(.*?)(?=^\s*\[|\Z)'
    match = re.search(section_pattern, text)
    line = key + ' = ' + json.dumps(value) + '\n'
    if not match:
        return text.rstrip() + '\n\n[' + section + ']\n' + line
    body = match.group(1)
    key_pattern = r'(?m)^\s*' + re.escape(key) + r'\s*=.*(?:\n|$)'
    body = re.sub(key_pattern, lambda _: line, body, count=1) if re.search(key_pattern, body) else line + body
    return text[:match.start(1)] + body + text[match.end(1):]
config_text = set_value(config_text, 'build', 'command', command)
config_text = set_value(config_text, 'build.environment', 'PYTHON_VERSION', '3.12')
verified = tomllib.loads(config_text)
if verified['build']['command'] != command:
    raise SystemExit('Could not verify the updated build command.')
package = json.loads((root / 'package.json').read_text())
package.setdefault('scripts', {})['build:netlify:verified'] = 'bash scripts/build-netlify-verified.sh'
package['scripts']['test:netlify-gate'] = "python3 -m unittest discover -s tests -p 'test_netlify_gate.py' -v"
writes['netlify.toml'] = config_text.encode()
writes['package.json'] = (json.dumps(package, indent=2) + '\n').encode()
ignore_path = root / '.gitignore'
ignore = ignore_path.read_text() if ignore_path.exists() else ''
for entry in ['.netlify/', '.sites-runtime/', 'next-env.d.ts', '*.tsbuildinfo']:
    if entry not in [line.lstrip('/') for line in ignore.splitlines()]:
        ignore = ignore.rstrip() + '\n' + entry + '\n'
writes['.gitignore'] = ignore.encode()
if (root / 'tsconfig.json').exists():
    ts = json.loads((root / 'tsconfig.json').read_text())
    ts.setdefault('compilerOptions', {})['tsBuildInfoFile'] = '.next/tsconfig.tsbuildinfo'
    writes['tsconfig.json'] = (json.dumps(ts, indent=2) + '\n').encode()
# Verify all inputs before replacing any project file. Replace files atomically.
for name, data in writes.items():
    path = root / name
    if path.exists() and path.read_bytes() == data:
        continue
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, staging = tempfile.mkstemp(prefix='.gate-install-', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data)
        os.chmod(staging, 0o755 if name.endswith('.sh') else 0o644)
        os.replace(staging, path)
    finally:
        if os.path.exists(staging):
            os.unlink(staging)
print('Installed verified build command, publication scanner, regression tests and cache exclusions.')
print('Run npm run test:netlify-gate, then npm run build:netlify:verified.')
INSTALLPY
